-- Base inicial de soluções (revisar com a equipe técnica)
-- Rode depois do schema.sql. Só insere se a tabela estiver vazia.
insert into public.base_solucoes (area, problema, solucao, resolve_na_hora, equipe)
select * from (values
('Pintura','Mancha, sujeira ou marca de mão na parede','Limpar com pano úmido e sabão neutro. Se não sair, retoque de pintura com a mesma tinta e cor (rolo pequeno, parede inteira de canto a canto para não marcar).',true,'Pintura'),
('Pintura','Respingo de tinta em piso, rodapé, tomada ou esquadria','Remover com espátula plástica e pano úmido; em esquadria de alumínio usar apenas pano e álcool, sem abrasivo.',true,'Limpeza'),
('Pintura','Falha de cobertura, pintura manchada ou com emenda aparente','Nova demão na parede inteira (canto a canto) com a mesma tinta e lote, após lixar levemente o local.',false,'Pintura'),
('Pintura','Fissura fina (fio de cabelo) no reboco ou na pintura','Abrir levemente a fissura, aplicar massa acrílica ou selante acrílico pintável, lixar e repintar o pano inteiro. Se a fissura for maior que 1 mm, inclinada ou em canto de porta/janela, chamar o engenheiro para avaliar.',false,'Pintura'),
('Pintura','Bolha, descascamento ou estufamento da pintura','Verificar se há umidade no local (encanamento, janela, área molhada). Sem umidade: raspar, aplicar fundo preparador, massa e repintar. Com umidade: registrar como Impermeabilização/umidade e chamar o engenheiro.',false,'Pintura'),
('Pintura','Massa ou parede ondulada, imperfeição visível com luz rasante','Avaliar com o cliente se é visível a 1 m de distância com luz normal. Se sim, lixar, aplicar massa, lixar e repintar o pano.',false,'Pintura'),
('Pintura','Pintura de porta de madeira com falha ou marca','Lixar levemente e retocar com o mesmo esmalte ou verniz; deixar secar com a porta aberta.',false,'Pintura'),
('Cerâmica e revestimentos','Rejunte faltando, falhado ou com buraco','Limpar a junta e completar com rejunte da mesma cor (ver memorial). Liberar uso da área molhada só depois da cura indicada na embalagem.',true,'Cerâmica'),
('Cerâmica e revestimentos','Rejunte sujo, manchado ou com resíduo de argamassa sobre a peça','Limpar com esponja e produto para limpeza pós-obra adequado ao revestimento (nunca ácido em porcelanato polido).',true,'Limpeza'),
('Cerâmica e revestimentos','Peça trincada, lascada ou quebrada','Substituir a peça: remover com cuidado, assentar peça do mesmo lote (verificar sobra no almoxarifado) e rejuntar.',false,'Cerâmica'),
('Cerâmica e revestimentos','Peça com som oco (desplacando) ao bater','Marcar as peças com fita. Remover e reassentar com argamassa de dupla colagem. Se forem várias peças seguidas, chamar o engenheiro.',false,'Cerâmica'),
('Cerâmica e revestimentos','Peças desalinhadas, desnível entre peças (dente)','Avaliar se o desnível é perceptível ao toque. Se for, reassentar as peças afetadas.',false,'Cerâmica'),
('Cerâmica e revestimentos','Recorte malfeito em torno de tomada, registro ou ralo','Ajustar com espelho/canopla maior quando possível; se não, substituir a peça com recorte correto.',false,'Cerâmica'),
('Piso','Caimento errado, água empoçando no box, varanda ou área de serviço','Testar com balde de água e fotografar onde empoça. Corrigir caimento exige refazer o piso do trecho: chamar o engenheiro.',false,'Cerâmica'),
('Piso','Piso riscado ou manchado','Tentar limpeza com produto adequado ao tipo de piso. Se o risco for permanente, substituir a peça.',false,'Cerâmica'),
('Piso','Rodapé solto, desalinhado ou com junta aberta','Recolar com cola/argamassa adequada e calafetar a junta superior com selante acrílico na cor da parede.',true,'Manutenção geral'),
('Piso','Soleira ou peitoril trincado, solto ou manchado','Se solto, recolar; se trincado ou lascado, substituir a peça de granito/mármore.',false,'Cerâmica'),
('Esquadrias e portas','Porta raspando no piso ou no batente, difícil de fechar','Apertar parafusos das dobradiças. Se continuar raspando, ajustar dobradiça (calço) ou aplainar a porta e repintar o topo.',true,'Esquadrias'),
('Esquadrias e portas','Fechadura ou maçaneta solta, emperrada ou não tranca','Apertar parafusos da maçaneta e da testa; alinhar a lingueta com a contratesta do batente (ajustar a chapa). Lubrificar com grafite, não com óleo.',true,'Esquadrias'),
('Esquadrias e portas','Chave faltando ou não funciona','Conferir o quadro de chaves da unidade com o almoxarifado. Testar todas as chaves em todas as portas antes de entregar.',true,'Manutenção geral'),
('Esquadrias e portas','Janela de correr pesada, travando ou saindo do trilho','Limpar o trilho (resíduo de obra é a causa mais comum), regular as roldanas e testar a trava.',true,'Esquadrias'),
('Esquadrias e portas','Janela sem vedação, entra vento ou água','Verificar escovas e borrachas de vedação e o selante entre esquadria e parede. Refazer a vedação com silicone/selante. Se houver sinal de infiltração, chamar o engenheiro.',false,'Esquadrias'),
('Esquadrias e portas','Esquadria de alumínio riscada ou amassada','Riscos leves: polir. Amassado ou risco profundo na pintura eletrostática: substituir o perfil ou a folha com o fornecedor.',false,'Esquadrias'),
('Esquadrias e portas','Porta de madeira empenada, lascada ou com batente danificado','Lascado pequeno: massa para madeira e retoque. Empenada ou batente danificado: substituir com a marcenaria.',false,'Esquadrias'),
('Esquadrias e portas','Guarnição (alizar) solta ou com fresta','Fixar com prego sem cabeça e cola, calafetar a fresta e retocar a pintura.',true,'Esquadrias'),
('Vidros','Vidro riscado, trincado ou quebrado','Substituir o vidro com a vidraçaria. Trinca é risco de acidente: isolar a área até a troca.',false,'Vidraçaria'),
('Vidros','Vidro sujo de tinta, argamassa ou etiqueta','Limpar com lâmina própria para vidro, água e detergente; nunca palha de aço.',true,'Limpeza'),
('Vidros','Box de vidro desalinhado, roldana ou puxador solto','Regular roldanas e apertar o puxador; conferir o silicone na base.',true,'Vidraçaria'),
('Elétrica','Tomada ou interruptor sem funcionar','1) Conferir se o disjuntor do circuito está ligado no quadro. 2) Testar com o testador de tomada. 3) Se não funcionar, abrir o espelho com o disjuntor desligado e verificar a conexão dos fios.',true,'Elétrica'),
('Elétrica','Espelho de tomada/interruptor torto, solto, quebrado ou faltando','Desligar o disjuntor, apertar os parafusos do módulo e encaixar o espelho alinhado; substituir se estiver quebrado.',true,'Elétrica'),
('Elétrica','Disjuntor desarmando ou DR caindo','Não religar repetidamente. Desligar os aparelhos, identificar o circuito e chamar o eletricista: pode haver fuga de corrente ou fio invertido.',false,'Elétrica'),
('Elétrica','Quadro de distribuição sem identificação dos circuitos','Identificar cada disjuntor com etiqueta conforme o projeto elétrico da unidade.',true,'Elétrica'),
('Elétrica','Ponto de luz sem funcionar ou sem fio aparente','Conferir disjuntor e interruptor; testar com lâmpada de teste. Se não acender, verificar a fiação no ponto.',true,'Elétrica'),
('Elétrica','Interfone, campainha ou ponto de TV/dados sem sinal','Testar a ligação até o quadro de comunicação/prumada; registrar e acionar o eletricista ou o fornecedor do interfone.',false,'Elétrica'),
('Hidráulica','Vazamento em registro, sifão ou ligação flexível','Fechar o registro, reapertar a conexão e refazer a vedação com fita veda-rosca; trocar o flexível ou a borracha do sifão se estiver danificado. Testar com água por alguns minutos.',true,'Hidráulica'),
('Hidráulica','Ralo ou pia com escoamento lento ou entupido','Retirar a grelha e limpar resíduo de obra (argamassa, rejunte). Se não resolver, desentupir e testar com água; se o problema persistir, chamar o engenheiro.',true,'Hidráulica'),
('Hidráulica','Baixa pressão de água em torneira ou chuveiro','Conferir se o registro geral e o da área estão totalmente abertos; limpar o arejador da torneira e o crivo do chuveiro (resíduo de obra é comum).',true,'Hidráulica'),
('Hidráulica','Mau cheiro saindo do ralo','Verificar se o ralo sifonado está com água (fecho hídrico) e com a grelha correta. Encher com água; se o cheiro continuar, chamar o encanador.',true,'Hidráulica'),
('Hidráulica','Água quente não chega ou aquecedor não liga','Conferir registro do aquecedor, gás/energia e a instalação conforme manual do fabricante; acionar o encanador ou a assistência do fabricante.',false,'Hidráulica'),
('Louças e metais','Vaso sanitário com vazamento contínuo na caixa acoplada','Regular a boia e o mecanismo de descarga; trocar o reparo se não vedar.',true,'Hidráulica'),
('Louças e metais','Vaso, pia ou tanque solto ou balançando','Reapertar a fixação; refazer o rejunte/silicone na base. Se a louça trincou, substituir.',true,'Hidráulica'),
('Louças e metais','Louça trincada, lascada ou riscada','Substituir a peça (verificar estoque ou garantia do fornecedor).',false,'Hidráulica'),
('Louças e metais','Torneira ou misturador pingando, solto ou com acabamento riscado','Apertar a fixação; trocar o vedante/reparo se pingar. Acabamento riscado: substituir pela garantia do fabricante.',true,'Hidráulica'),
('Louças e metais','Silicone faltando ou sujo em pia, tanque ou box','Remover o silicone velho, limpar e aplicar silicone acético/antifungo novo; não molhar por 24 h.',true,'Manutenção geral'),
('Gesso e forro','Fissura ou trinca no forro de gesso','Aplicar fita e massa de gesso na junta, lixar e repintar. Se a fissura acompanhar mancha de umidade, chamar o engenheiro.',false,'Gesso'),
('Gesso e forro','Forro ou sanca com mancha, ondulação ou desnível','Mancha amarelada costuma indicar umidade: investigar a origem antes de reparar. Ondulação: corrigir com massa e repintar.',false,'Gesso'),
('Gesso e forro','Alçapão ou tampa de inspeção desalinhada','Ajustar o encaixe e o acabamento; retocar a pintura.',true,'Gesso'),
('Umidade e infiltração','Mancha de umidade, mofo ou infiltração em parede ou teto','Não pintar por cima. Fotografar, marcar a área e chamar o engenheiro para achar a origem (tubulação, janela, laje, área molhada vizinha). Só repintar depois de resolvida a causa e com a parede seca.',false,'Manutenção geral'),
('Umidade e infiltração','Água entrando por janela ou porta da varanda em chuva','Verificar caimento do peitoril, drenos da esquadria (desentupir) e vedação com selante. Persistindo, chamar o engenheiro.',false,'Esquadrias'),
('Limpeza','Unidade com resíduo de obra, poeira ou sujeira','Acionar a equipe de limpeza fina antes de continuar a entrega; não deixar o cliente sair com a impressão de obra suja.',true,'Limpeza'),
('Limpeza','Etiquetas, plásticos de proteção ou fitas deixados','Remover na hora (esquadrias, louças, metais, vidros).',true,'Limpeza'),
('Outros','Item do memorial descritivo faltando ou diferente do contratado','Conferir com o memorial e o contrato da unidade (inclusive personalizações). Registrar e encaminhar ao engenheiro e ao comercial; não prometer prazo ao cliente sem confirmação.',false,'Manutenção geral'),
('Outros','Dúvida do cliente sobre uso, garantia ou manutenção','Mostrar o Manual do Proprietário (prazos de garantia por sistema e manutenções previstas). Se não souber responder, anotar a pergunta para o engenheiro retornar.',true,''),
('Outros','Dano que parece ter sido causado após a vistoria (mudança, terceiros)','Registrar com foto, data e hora; se for na entrega, ainda é responsabilidade da construtora. Comunicar o engenheiro.',false,'Manutenção geral')
) as v(area, problema, solucao, resolve_na_hora, equipe)
where not exists (select 1 from public.base_solucoes);
